      phone: "+44 20 7946 0919",
      company: "Cyberdyne Systems",
      notes: "Valid international UK lead"
    }
  }
];

const item = $input.item.json;

// 1. Clean and lowercase email
const cleanEmail = String(item.email || '')
  .trim()
  .toLowerCase();

// 2. Clean phone number
let rawPhone = String(item.phone || '').trim();

let cleanPhone = rawPhone.replace(/[^\d+]/g, '');

// Convert US phone numbers to E.164 format
if (/^\d{10}$/.test(cleanPhone)) {
  cleanPhone = '+1' + cleanPhone;
} else if (/^1\d{10}$/.test(cleanPhone)) {
  cleanPhone = '+' + cleanPhone;
}

// 3. Clean name and company
const cleanName = String(item.name || '').trim();

const cleanCompany = String(item.company || '').trim();

// 4. Return cleaned lead
return {
  json: {
    leadId: item.leadId,
    name: cleanName,
    email: cleanEmail,
    phone: cleanPhone,
    company: cleanCompany,
    rawNotes: item.notes
  }
};

const lead = $input.item.json;

const errors = [];

// Validate customer name
if (!lead.name || lead.name.trim().length < 2) {
  errors.push("Invalid customer name");
}

// Validate email format
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!emailRegex.test(lead.email || "")) {
  errors.push("Invalid email format");
}

// Check disposable email domains
const blockedDomains = [
  "mailinator.com",
  "tempmail.com",
  "10minutemail.com"
];

const emailDomain = String(lead.email || "")
  .split("@")[1] || "";

if (blockedDomains.includes(emailDomain)) {
  errors.push("Disposable email domain");
}

// Validate international phone number
const phoneRegex = /^\+[1-9]\d{7,14}$/;

if (!phoneRegex.test(lead.phone || "")) {
  errors.push("Invalid phone number");
}

// Return validation result
return {
  json: {
    ...lead,
    isQualityLead: errors.length === 0,
    validationStatus:
      errors.length === 0 ? "VALID" : "INVALID",
    validationErrors: errors
  }
};

const leads = $input.all();
const seenEmails = new Set();

return leads.map((item) => {
  const lead = item.json;

  const email = String(lead.email || "")
    .trim()
    .toLowerCase();

  const isDuplicate = seenEmails.has(email);

  if (!isDuplicate) {
    seenEmails.add(email);
  }

  return {
    json: {
      ...lead,
      isUniqueLead: !isDuplicate,
      duplicateStatus: isDuplicate
        ? "DUPLICATE"
        : "UNIQUE"
    }
  };
});
